import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA source for diag(A) @ B
diagmm_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void diagmm_kernel(const float* A, const float* B, float* C, int N, int M) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * M;
    if (idx < total) {
        int row = idx / M;
        C[idx] = A[row] * B[idx];
    }
}

torch::Tensor diagmm_cuda(torch::Tensor A, torch::Tensor B) {
    int64_t N = A.size(0);
    int64_t M = B.size(1);
    auto out = torch::zeros_like(B);

    int block_size = 256;
    int grid_size = (N * M + block_size - 1) / block_size;

    diagmm_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        out.data_ptr<float>(),
        N,
        M
    );

    return out;
}
"""

diagmm_cpp_source = r"""
torch::Tensor diagmm_cuda(torch::Tensor A, torch::Tensor B);
"""

# Compile the inline CUDA code
diagmm = load_inline(
    name="diagmm",
    cpp_sources=diagmm_cpp_source,
    cuda_sources=diagmm_source,
    functions=["diagmm_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    """
    Optimized model that performs C = diag(A) * B using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.diagmm = diagmm

    def forward(self, A, B):
        return self.diagmm.diagmm_cuda(A, B)

M = 4096
N = 4096

def get_inputs():
    A = torch.randn(N)
    B = torch.randn(N, M)
    return [A, B]

def get_init_inputs():
    return []
